'use strict';
const KEY='data-analysis-lab-v1';let work={};try{work=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}let game=0,lesson=0,sim=0;const cleanRows=Stats.clean(EDUCATION);const main=document.querySelector('main');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=3)=>Number.isFinite(x)?x.toFixed(d):'—';
const val=k=>work[k]??'';
function save(){try{localStorage.setItem(KEY,JSON.stringify(work));document.querySelectorAll('.save-state').forEach(x=>x.textContent='נשמר במכשיר זה')}catch{document.querySelectorAll('.save-state').forEach(x=>x.textContent='השמירה אינה זמינה; ייצאו את העבודה')}}
const field=(k,label,placeholder='')=>`<label>${label}<textarea data-save="${k}" placeholder="${esc(placeholder)}">${esc(val(k))}</textarea></label>`;
const num=(id,label,value='',min='',max='',step='any')=>`<label>${label}<input type="number" id="${id}" data-save="${id}" value="${esc(work[id]??value)}" ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} step="${step}"></label>`;
const select=(id,label,options,value='')=>`<label>${label}<select id="${id}" data-save="${id}"><option value="">בחרו…</option>${options.map((o,i)=>`<option value="${i}" ${String(value)===String(i)?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const solution=t=>`<details><summary>פתרון לדוגמה והסבר</summary><div class="source-note">${t}</div></details>`;
const notice=()=>`<div class="notice"><strong>תיקי תרגול מדומים.</strong> כל התלמידים, התשובות, מדידות החיישנים ופלטי ה־AI נוצרו להוראה. אין חיבור לשירות AI ואין צורך בחשבון. בחירות וחישובים מקבלים משוב אוטומטי; נימוקים נבדקים עצמית או עם מורה.</div>`;
const head=(mini,title,text='')=>`<div class="route-head"><span class="eyebrow">${mini}</span><h1>${title}</h1><p class="lead">${text}</p></div>`;
const table=(headers,rows)=>`<div class="scroll-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const ncell=x=>`<span class="metric">${x===null?'חסר':esc(x)}</span>`;
function dataTable(rows){const gain='gain' in rows[0];return table(['id','group','pre','post','hours',...(gain?['gain']:[])],rows.map(r=>[r.id,esc(r.group),ncell(r.pre),ncell(r.post),ncell(r.hours),...(gain?[ncell(r.gain)]:[])]));}
function tabs(names,kind,index){return `<div class="subnav" role="tablist" aria-label="בחירת פעילות">${names.map((n,i)=>`<button role="tab" aria-selected="${i===index}" data-${kind}="${i}">${i+1}. ${n}</button>`).join('')}</div>`;}
const feedback=(id)=>`<div id="${id}" class="feedback" role="status" aria-live="polite"></div>`;
function quiz(id,q,options,answer,explain){return `<div class="question"><h3>${q}</h3><div class="options">${options.map((o,i)=>`<button data-quiz="${id}" data-choice="${i}" data-answer="${answer}" data-explain="${esc(explain)}">${o}</button>`).join('')}</div>${feedback(id)}</div>`;}
function home(){return `<section class="hero"><div><span class="eyebrow">שואלים · מנקים · מנתחים · מפרשים</span><h1>המספר נכון.<br>ומה המסקנה?</h1><p class="lead">מעבדת נתונים לתיכון ולי״ג–י״ד. לומדים לקבל החלטות שאפשר לנמק, לשחזר ולבדוק — לפני שמאמינים לפלט של AI.</p><div class="actions"><a class="button primary" href="#education">פותחים את תיק הנתונים ↗</a><a class="button" href="#learn">מתחילים בלמידה</a></div><span class="pill">3 תיקים</span><span class="pill green">6 משחקים</span><span class="pill gold">4 סימולציות</span></div><div class="hero-visual"><img src="images/data-desk.jpg" class="hero-photo" alt="בדיקת תרשימים ונתונים לצד מחשב — תמונת אווירה שנוצרה ב-AI" width="1600" height="900"><div class="evidence-node"><span class="mini">01 / לפני החישוב</span><h3>מה השאלה, ומה היחידה?</h3></div><div class="connector">↓</div><div class="evidence-node"><span class="mini">02 / בתוך הנתונים</span><h3>איזו החלטה שינתה את התוצאה?</h3></div><div class="connector">↓</div><div class="evidence-node"><span class="mini">03 / אחרי הפלט</span><h3>מה הראיה, ומה עדיין לא ידוע?</h3></div></div></section><section class="media-section" aria-labelledby="media-heading"><div class="section-title"><div><span class="eyebrow">צופים · מקשיבים · בודקים</span><h2 id="media-heading">ניתוח נתונים — גם בווידאו ובאודיו</h2></div><a class="button" href="#education">מההסבר לתרגול ←</a></div><div class="media-grid"><article class="media-card video-card"><span class="media-label">סרטון · 6:12 דקות</span><h3 lang="en" dir="ltr">Designing the Unbreakable Data Pipeline</h3><video controls playsinline preload="metadata" poster="images/data-desk.jpg" aria-label="Designing the Unbreakable Data Pipeline"><source src="media/data-pipeline.mp4" type="video/mp4">הדפדפן אינו תומך בניגון וידאו.</video><a href="media/data-pipeline.mp4" download>הורדת הסרטון</a></article><article class="media-card audio-card"><img src="images/sensor-lab.jpg" alt="עבודה עם חיישנים ונתונים במעבדה — תמונת אווירה שנוצרה ב-AI" class="audio-photo" width="1600" height="900" loading="lazy"><div class="audio-content"><span class="media-label">הקלטה · 16:03 דקות</span><h3>מהירות מול אמינות בניתוח נתונים בבינה מלאכותית</h3><audio controls preload="metadata" aria-label="מהירות מול אמינות בניתוח נתונים בבינה מלאכותית"><source src="media/speed-and-reliability.m4a" type="audio/mp4">הדפדפן אינו תומך בניגון אודיו.</audio><a href="media/speed-and-reliability.m4a" download>הורדת ההקלטה</a></div></article></div><p class="media-note">אחרי הצפייה או ההאזנה: בחרו החלטת ניתוח אחת, רשמו איזו ראיה מצדיקה אותה ומה עוד צריך לבדוק. תמונות האווירה נוצרו ב־AI.</p></section><div class="grid">${[['01','41 שורות. 40 תלמידים.','מאתרים כפילות, חסרים וערך שדורש מקור מאמת.','education'],['02','לא רק לספור קולות','מקשרים קטעים מדויקים לקודים, תמות ומקרים שמאתגרים אותן.','qual'],['03','יציב יותר. איטי יותר.','משווים חיישנים מזווגים ומבררים את פשרת התכנון.','engineering']].map(c=>`<article class="card"><span class="number">${c[0]}</span><h2>${c[1]}</h2><p>${c[2]}</p><a href="#${c[3]}">למעבדה ←</a></article>`).join('')}</div>${notice()}<section class="panel"><h2>מסלול מלא מהשאלה להגנה אישית</h2><p>ארבעה מפגשים בני 90 דקות, הסברים, דוגמאות פתורות, משחקים, גרפים וסימולציות עם זרע לשחזור. כל חישוב רץ בדפדפן. הפעילויות המלאות וחלק מההגנות דורשות מפגש הרחבה מעבר לארבעת המפגשים.</p><div class="horizontal"><a class="button" href="#games">לששת המשחקים</a><a class="button" href="#sim">לארבע הסימולציות</a><a class="button" href="#portfolio">לתיק העבודה והייצוא</a></div></section>`;}
function learn(){const l=LESSONS[lesson];return head('ארבעה מפגשים · 90 דקות כל אחד','לומדים לחשוב עם נתונים')+tabs(LESSONS.map(x=>x.title),'lesson',lesson)+`<section class="panel"><h2>מפגש ${lesson+1}: ${l.title}</h2><p>${l.goal}</p><p>${l.explain}</p><div class="split"><div><h3>סדר המפגש</h3><ul class="timeline">${l.timeline.map(x=>`<li>${x}</li>`).join('')}</ul></div><div>${quiz('lesson-q',l.q,l.options,l.answer,l.solution)}${field('lesson-reason'+lesson,'הסבירו את הבחירה במילים שלכם')}${field('lesson-exit'+lesson,'כרטיס יציאה: '+l.exit)}${solution(l.solution)}</div></div></section><section class="panel"><h2>מילון מושגים שימושי</h2>${CONCEPTS.map(([a,b])=>`<details><summary>${a}</summary><p>${b}</p></details>`).join('')}<p class="source-note">הסדר: שאלה והקשר ← יחידה ומשתנים ← מבנה נתונים ← איכות ← תיאור והמחשה ← ניתוח ← בדיקת חישוב ← פרשנות ומגבלות.</p></section>`;}
function statsTable(rows){const r=[];for(const g of ['AI','CONTROL'])for(const v of ['pre','post','gain','hours']){const s=Stats.summary(rows.filter(x=>x.group===g).map(x=>x[v]));r.push([g,v,s.n,fmt(s.mean),fmt(s.median),fmt(s.sd),fmt(s.min),fmt(s.max)]);}return table(['קבוצה','משתנה','n','ממוצע','חציון','SD מדגמית','מינימום','מקסימום'],r);}
function inference(r,label='הפרש AI פחות CONTROL'){return `<div class="stats-row"><div class="stat"><span>${label}</span><strong class="metric">${fmt(r.difference)}</strong></div><div class="stat"><span>95% CI להפרש</span><strong class="metric">[${fmt(r.low)}, ${fmt(r.high)}]</strong></div><div class="stat"><span>p דו־צדדי</span><strong class="metric">${r.p<.001?'&lt;0.001':fmt(r.p)}</strong></div><div class="stat"><span>יחידות בניתוח</span><strong>${r.n}</strong></div></div><p class="small">SE=${fmt(r.se)} · t=${fmt(r.t)} · df=${fmt(r.df)}${r.g!==undefined?' · Hedges g='+fmt(r.g):''}. זהו חישוב מותנה במערך ובנתונים, ולא אימות של כל הנחות המחקר.</p>`;}
function education(){const r=Stats.educational(cleanRows);return head('תיק א · עמ׳ 7–9, 36–37','האם השיפור הממוצע שונה?','40 תלמידים הוגרלו אישית למשוב AI מובנה או למשוב כתוב, 20 בכל תנאי. קדם וסיום מזווגים בתוך תלמיד; השיפור מושווה בין קבוצות.')+notice()+`<section class="panel"><h2>מילון ורישום מקור</h2><p><b>id</b>: מזהה מדומה; <b>group</b>: AI או CONTROL; <b>pre / post</b>: ציון 0–100; <b>hours</b>: שעות תרגול; <b>gain</b>: post−pre לאחר ניקוי.</p><div class="source-note"><b>source_register:</b> מזהה S07, עמודה post, ערך מאומת 69. אין מקור מאמת לציון החסר של S12. שעות S25=10 אומתו כאמיתיות בסיפור.</div>${field('edu-question','נסחו את השאלה, יחידת הניתוח, האומדן והנחות העצמאות')}<div class="export-actions"><button data-download="raw">הורדת CSV גולמי</button><button data-download="clean">הורדת CSV נקי</button><button data-download="register">הורדת רישום המקור</button><button data-download="cleanlog">הורדת יומן הניקוי לדוגמה</button></div><details><summary>41 שורות המקור — ללא שינוי</summary>${dataTable(EDUCATION)}</details></section><section class="panel"><h2>שש החלטות, לא שש מחיקות</h2>${CLEANING.map(([id,issue,action,why],i)=>`<details><summary>${id}: ${issue}</summary><p><b>${action}.</b> ${why}</p></details>`).join('')}<p>40 תלמידים נקיים; 39 שיפורים; 38 זוגות שעות–סיום. השלמים עלולים להיות מוטים אם החוסר קשור לתוצאה.</p><details><summary>העותק הנקי עם gain</summary>${dataTable(cleanRows)}</details>${field('clean-ownlog','יומן אישי: מזהה, ערך קודם, פעולה, ראיה, נימוק והשפעה על n')}</section><section class="panel"><h2>תיאור לפי קבוצה</h2>${statsTable(cleanRows)}<p class="note">SD מחושבת עם מחלק n−1. ממוצע gain משתמש בזוגות שלמים; חיסור ממוצע post של 19 מממוצע pre של 20 אינו אותה פעולה.</p>${quiz('edu-n','כמה תלמידים נכללים בהשוואת השיפור?',['40','39','38'],1,'ל־S12 חסר post; S18 נשאר למרות hours חסר. 19 AI ו־20 CONTROL.')}</section><section class="panel"><h2>Welch דו־צדדי על השיפור</h2>${inference(r)}${ciChart([r],['AI − CONTROL'],'Difference in gain · score points')}<p>השיפור הממוצע גדול בכ־1.8 נקודות בקבוצת AI, אך הטווח רחב וכולל אפס. אין הוכחת יתרון או שקילות ואין הכללה לכל גיל, כלי או מקצוע. קיימת אי־התאמה מקרית בקדם; השוואת סיום בלבד עונה על שאלה אחרת. ANCOVA היא הרחבה הדורשת בדיקת הנחות, ולא בחירה בדיעבד לפי p.</p>${field('edu-conclusion','מסקנה אישית: אומדן, אי־ודאות, הנחה ומגבלה')}${solution('gain = post − pre<br>SE = √(s²AI/nAI + s²CONTROL/nCONTROL)<br>t = (meanAI − meanCONTROL)/SE<br>במסמך: הפרש 1.797; SE=1.889; t=0.951; df=36.928; p=0.348; CI=[−2.031,5.626]; g=0.298.')}<a href="#sim">לבדיקת רגישות להחלטות טיפול ←</a></section>`;}
function quoteCards(edit=true){return QUOTES.map(([id,text])=>`<article class="quote"><small>${id}</small><p>${text}</p>${edit?field('code-'+id,'קוד, ציטוט קצר מדויק ופרשנות')+field('alt-'+id,'קריאה חלופית או מידע חסר'):''}</article>`).join('');}
function qual(){return head('תיק ב · עמ׳ 10–11, 13','מה עוזר להתקדם בפרויקט?','שאלה: מה מקשה על תלמידים לקדם פרויקט גמר, ואיזו עזרה מאפשרת להם להתקדם? יחידת הקידוד היא קטע בעל משמעות. אפשר כמה קודים לאותו קטע.')+notice()+`<section class="panel"><h2>קוראים לפני שמקודדים</h2><p>תחילה קוראים את כל 12 התשובות וכותבים הערת פרשנות. אחר כך מציעים קודים, משווים חלופות ובונים תמות. זו גישה תמטית רפלקסיבית לימודית; הפתרונות אינם תשובה חבויה אחת.</p>${field('qual-first','הערה ראשונית: מה בולט ומה הנחתם מראש?')}<button data-download="quotes">הורדת תיק הקולות כ־CSV</button>${quoteCards()}<p>Q12 יכול להצביע על נגישות למרות הסתייגות הדובר, או להישאר מחוץ למוקד בהנמקה. אין להמציא הבהרה שלא נאספה.</p></section><section class="panel"><h2>בונים שתי תמות עם גבולות</h2>${[1,2].map(i=>`<fieldset><legend>תמה ${i}</legend>${field('theme'+i,'משפט משמעות, לא רק שם נושא')}${field('theme-evidence'+i,'שני מזהים וציטוטים מדויקים התומכים בתמה')}${field('theme-limit'+i,'מקרה שמאתגר את התמה וקריאה חלופית')}</fieldset>`).join('')}${solution('תמות אפשריות: התקדמות דורשת גבול ברור להחלטה (Q01,Q07); עזרה מועילה כשהיא משאירה יכולת לבדוק ולהסביר (Q03,Q04,Q05,Q06,Q08,Q10,Q11); משאבים אינם עוזרים אם אי אפשר לגשת אליהם בזמן (Q02,Q09,Q12). חלופה: ארגון סביב שליטה בפרויקט — דרישות, ידע וגישה. אין חובה לכפות שלוש תמות. Q07 סותר מחסור גורף במשאבים, בלי להוכיח שמשאבים אינם חשובים לאחרים.')}<p class="note">בגישה רפלקסיבית דיון בין קוראים מרחיב פרשנות; אחוז הסכמה אינו מבחן תוקף של תמה. בגישת ספר קודים נפרדת אפשר להגדיר יחידות וכללי הכללה ולהדגים הסכמה, אך אין לערבב את שתי הגישות.</p></section><section class="panel"><h2>מבקרים פלט AI מוכן</h2><blockquote>״כל 12 התלמידים מתקשים לתכנת ולכן מעדיפים AI. Q04 אומר: המודל עושה הכול בשבילי. התמה המרכזית היא מחסור בציוד.״</blockquote>${quiz('qual-fake','מה הבעיה בציטוט שיוחס ל־Q04?',['ציטוט מדויק','ציטוט שאינו מופיע במקור'],1,'Q04 מדבר על חבר שמסביר בלי לעשות במקומו; הפלט החליף דובר ומשמעות.')}${field('qual-audit','תעדו לפחות שלוש חריגות: טענה, מקור, תיקון ונימוק')}${solution('הכללה לכולם אינה נתמכת; Q04 שוכתב לציטוט שלא קיים; Q07 סותר חוסר גורף בציוד; העדפה גורפת ל־AI אינה מסקנת התיק; Q08 מתאר גם שימוש מועיל וביקורתי. פלט חלקי תקין: יש קושי בהכוונת הפרויקט ובנגישות לתמיכה; Q03,Q08 מצביעים על צורך לאמת סיוע. גם הוא אינו מכסה את כל הקולות.')}</section>${integration()}`;}
function integration(){return `<section class="panel"><h2>שילוב שאינו כופה התאמה</h2><p>התיק החינוכי ותיק הקולות אינם מאותם תלמידים. אין לקשור Q10 לאדם מסוים בקובץ הציונים. זו טבלת חשיבה לתכנון מחקר עתידי, לא הוכחת מנגנון.</p>${table(['ממצא כמותי','קטע','יחס אפשרי ובדיקה נוספת'],[['יתרון שיפור קטן ולא מובהק','Q10: פתרון עובד בלי הסבר','השערה: ביצוע אינו הבנה. דרוש מדד עצמאי וקישור מתוכנן.'],['קשר שעות–ציון רגיש לחריג','Q02: עבודה וזמינות מעבדה','אפשר לבדוק נגישות וזמן בעתיד; אינו הסבר למתאם הקיים.'],['סיום CONTROL גבוה, שיפור AI גדול יותר','Q08: תועלת נתפסת','מדדים שונים אינם בהכרח סתירה.'],['המסנן מפחית תנודתיות','Q05: מד ייחוס','מחדד יציבות מול דיוק; אין קשר אמפירי בין התיקים.']])}${field('integration-gap','בחרו פער אחד, שני הסברים מתחרים ונתון חדש שיבדיל ביניהם')}${quiz('mix-count','8 מתוך 12 קטעים קיבלו קוד. האם 67% מכל תלמידי המכללה חושבים כך?',['כן','לא'],1,'זו שכיחות בתוך תיק מדומה קטן; הקטעים והקידוד אינם מדגם מייצג של האוכלוסייה.')}<details><summary>תכנון משולב אפשרי</summary><p>שאלה משותפת מראש; מדד ביצוע ללא סיוע; בחירת מקרים איכותניים לפי דפוסים; איסוף מורשה; טבלה משותפת שמציגה גם סתירות. אפשר תכנון עוקב או מקביל; שילוב אינו תמיד אמין יותר.</p></details></section>`;}
function engineering(){const units=unitMeans(),s=Stats.paired(units.map(x=>x.filterSD),units.map(x=>x.rawSD)),t=Stats.paired(units.map(x=>x.filterMS),units.map(x=>x.rawMS));return head('תיק ג · עמ׳ 12, 38','פחות תנודות. יותר זמן.','שש יחידות חיישן, שלוש הרצות בכל אחד משני מצבים. סדר ההרצות מאוזן בסיפור. sd_c הוא SD בתוך הרצה; response_ms הוא זמן תגובה ל־90% ממדרגה.')+notice()+`<section class="panel"><h2>הרצה אינה יחידה עצמאית</h2><p>מאגמים שלוש הרצות בכל מצב בתוך חיישן, ואז משווים שישה הפרשים מזווגים. 36 שורות אינן 36 חיישנים.</p><p class="note">החישובים כאן מבוססים על הערכים המעוגלים בנספח PDF. הקבצים הנלווים ברמת הדיוק המקורית לא סופקו. לכן תיתכן סטייה קלה מתוצאות המדריך; תוצאותיו מסומנות בנפרד.</p><button data-download="engineering">הורדת 36 המדידות מהנספח</button><details><summary>כל המדידות המעוגלות</summary>${table(['unit','run','mode','sd_c °C','response_ms'],ENGINEERING.map(r=>[r.unit,r.run,r.mode,ncell(r.sd_c),ncell(r.response_ms)]))}</details><h3>ממוצעים בתוך יחידה ומצב</h3>${table(['יחידה','RAW SD °C','FILTER SD °C','RAW ms','FILTER ms'],units.map(r=>[r.unit,fmt(r.rawSD,5),fmt(r.filterSD,5),fmt(r.rawMS),fmt(r.filterMS)]))}${quiz('engineering-n','מה n להשוואה המזווגת?',['36','18','6'],2,'היחידה היא חיישן; שלוש הרצות בתוך כל מצב מאוגמות לפני ההשוואה.')}</section><section class="panel"><h2>FILTER פחות RAW — חישוב מהנספח</h2><h3>תנודתיות °C</h3>${inference(s,'הפרש SD בתוך הרצה')}<h3>זמן תגובה ms</h3>${inference(t,'הפרש זמן תגובה')}<p class="source-note">תוצאות המדריך מהנתונים המלאים: SD ממוצע 0.40444→0.22350, הפרש −0.18094, CI [−0.18631,−0.17558]. זמן 102.811→283.561 ms, הפרש 180.750, CI [174.977,186.523]. ירידה בתנודתיות כ־44.74%; זמן תגובה פי כ־2.758. בשניהם p&lt;0.001. ב־n=6 יש לבדוק הנחת התפלגות הפרשים ולהיזהר מהכללה.</p><p>ירידה בתנודתיות אינה הוכחת דיוק מול ערך אמת. לא נבדקו כיול, אמינות ארוכת טווח ותנאי סביבה נוספים. המדדים נעים בכיוונים שונים; p אינו מחליף דרישות תכנון.</p><div class="inputs">${num('limit-ms','תגובה מרבית מותרת (ms)',150,1,2000,1)}${num('limit-sd','SD מרבי מותר (°C)',.25,.01,2,.01)}</div><button id="filter-decision">בדיקת התאמה לדרישות המדומות</button>${feedback('filter-feedback')}${field('engineering-choice','החלטת תכנון: פשרה, מגבלה ובדיקה נוספת')}<p class="small">ספי התרגיל אינם תקן. הבדיקה משווה ממוצעים בלבד ואינה אישור רכיב לכל יחידה.</p></section>`;}
function unitMeans(){return Array.from({length:6},(_,i)=>{const unit='U'+(i+1),rows=ENGINEERING.filter(r=>r.unit===unit),m=(mode,k)=>Stats.mean(rows.filter(r=>r.mode===mode).map(r=>r[k]));return {unit,rawSD:m('RAW','sd_c'),filterSD:m('FILTER','sd_c'),rawMS:m('RAW','response_ms'),filterMS:m('FILTER','response_ms')};});}
const GAME_NAMES=['בלשי הנתונים','אותו ממוצע, סיפור אחר','מי בחר את המבחן','בית המשפט של הגרף','ציידי התמות','חדר בריחה מנתונים'];
function games(){return head('שישה משחקים · עמ׳ 14–18','משחקים, מנמקים וחוזרים לראיה')+tabs(GAME_NAMES,'game',game)+notice()+`<section class="panel"><h2>${GAME_NAMES[game]}</h2>${[detective,spread,chooseTest,court,hunters,escapeRoom][game]()}</section>`;}
function detective(){return `<p>20 דקות, שלושה תפקידים מתחלפים: חוקר, מבקר ומתעד. מצאו שש החלטות. אל תשנו את המקור. כאן נבדקת הבחירה אוטומטית; נימוק וראיה נבדקים לפי המפתח.</p><a href="#education">למקור, למילון ולרישום המאמת</a>${CLEANING.map(([id,issue,action,why],i)=>`<fieldset><legend>${id}: ${issue}</legend>${select('detect-'+i,'החלטה',CLEANING.map(r=>r[2]),val('detect-'+i))}${field('detect-reason'+i,'ראיה, נימוק והשפעה על n')}</fieldset>`).join('')}<button id="detect-check">בדיקת שש ההחלטות</button>${feedback('detect-feedback')}${solution('שש החלטות עם נימוק = 12 נקודות, שתי נקודות לכל אחת. במפגש מורה: מפחיתים שתי נקודות למחיקה או השלמה ללא ראיה, ומאפשרים תיקון. '+CLEANING.map(r=>`${r[0]}: ${r[2]} — ${r[3]}`).join('<br>'))}${field('detect-exit','אם שתי שורות אותו מזהה היו שני מועדי מדידה, איזו החלטה הייתה משתנה?')}`;}
function spread(){return `<p>15 דקות. קבוצה A: 68,69,70,71,72. קבוצה B: 50,60,70,80,90. חשבו, שרטטו ונמקו אם הן זהות.</p><div class="plot-grid">${dotPlot([68,69,70,71,72],'Group A')}${dotPlot([50,60,70,80,90],'Group B')}</div><div class="inputs">${num('spread-mean','הממוצע בשתי הקבוצות')}${num('spread-med','החציון בשתי הקבוצות')}${num('spread-ra','טווח A')}${num('spread-rb','טווח B')}${num('spread-sda','SD מדגמית A')}${num('spread-sdb','SD מדגמית B')}</div><button id="spread-check">בדיקת החישובים</button>${feedback('spread-feedback')}${field('spread-why','האם ההתפלגויות זהות? מה אפשר ומה אי אפשר להסביר?')}${solution('בשתי הקבוצות ממוצע וחציון 70 ואין שכיח יחיד. טווח A=4 ו־SD=1.581; טווח B=40 ו־SD=15.811. אין בסיס לזהות את סיבת הפיזור. ניקוד מורה מתוך 10: מרכז 2, פיזור 2, גרף 2, נימוק 2, הימנעות מסיבתיות 2.')}<h3>צרו קבוצה שלישית</h3><label>חמישה מספרים, ממוצע 70 וחציון שונה מ־70<input id="spread-custom" type="text" placeholder="50,50,60,90,100" value="${esc(val('spread-custom'))}" data-save="spread-custom" dir="ltr"></label><button id="custom-check">בדיקת הקבוצה שלי</button>${feedback('custom-feedback')}`;}
function chooseTest(){return `<p>20 דקות. לכל כרטיס בחרו ניתוח, כתבו תנאי ושאלת הבהרה. בחירה מוצעת אינה היתר להפעיל מבחן בלי בדיקת הנתונים.</p>${ANALYSES.map(([q,a,why],i)=>`<fieldset><legend>כרטיס ${i+1}</legend><p>${q}</p>${select('analysis-'+i,'ניתוח מוצע',ANALYSIS_OPTIONS,val('analysis-'+i))}${field('analysis-condition'+i,'תנאי ונימוק')}${field('analysis-question'+i,'שאלת הבהרה נדרשת')}</fieldset>`).join('')}<button id="analysis-check">בדיקת בחירות</button>${feedback('analysis-feedback')}${solution(ANALYSES.map((r,i)=>`${i+1}. ${r[2]}`).join('<br>')+'<p>ניקוד מורה מתוך 18: ניתוח, נימוק ושאלת הבהרה בכל כרטיס. ״אין מספיק מידע״ יכול להיות פתרון מלא כשהחסר מוסבר. נורמליות אינה מתג יחיד; גם לחלופה סודרת צריך לדעת מה היא בודקת.</p>')}${field('analysis-exit','תקנו את מלכודת AI: ״יש שתי קבוצות ולכן תמיד t בלתי תלוי״.')}`;}
function court(){return `<p>20 דקות. מציג, סנגור הגרף ומבקר. כל הכרעה דורשת הפניה לציר, לנתון או למכנה.</p><a href="#graphs">לגרפים האינטראקטיביים ←</a>${COURT.map(([q,a,why],i)=>quiz('court'+i,q,['חישוב נכון עם בסיס מוגדר','פרשנות מספרית שגויה','סיבתיות שאינה נתמכת','חסרות דרישות להכרעה'],a,why)+field('court-evidence'+i,'ראיה ומסקנה מתוקנת')).join('')}${field('court-title','כתבו כותרת לא סיבתית לגרף שעות–ציון')}${solution('כותרת אפשרית: הקשר בין שעות תרגול לציון סיום בתיק חינוכי מדומה. ניקוד מורה: שתי נקודות לכל טענה (סיווג וראיה), ועוד שלוש לתיקון גרף או כותרת — 15 בסך הכול. אפשר להטעות בלי לשנות אף מספר באמצעות ציר, מכנה, בחירת מדד או ניסוח.')}`;}
function hunters(){return `<p>25 דקות. כל תלמיד מציע תחילה שני קודים לבד. בנו שתי תמות, הציגו קטע תומך ומקרה מגביל לכל תמה. אין ניקוד על זהות להצעת AI.</p><details><summary>פתיחת 12 קטעי המקור</summary>${quoteCards(false)}</details>${field('hunter-code1','קוד ראשון: מזהה, ציטוט ומשמעות')}${field('hunter-code2','קוד שני: מזהה, ציטוט ומשמעות')}${[1,2].map(i=>field('hunter-theme'+i,'תמה '+i+': משפט משמעות, ראיה ומקרה מגביל')).join('')}${quiz('hunter-q','מה ההבדל בין Q03 ל־Q08?',['שניהם מוכיחים שכולם מעדיפים AI','Q03 מתאר המצאה; Q08 מתאר תועלת עם אימות'],1,'יש כאן חוויות ומשמעויות שונות. אין למחוק את ההבדל תחת תווית אחת רחבה.')}${field('hunter-q6','האם Q06 הוא רק חוסר ידע? כיצד Q12 יכול להיקרא?')}${solution('Q06 כולל גם תנאי חברתי של בושה בשאלה. Q12 מאפשר קריאה של נגישות או גבול מנומק למוקד. תמה אינה מוכרעת רק ברוב; מקרה יחיד יכול להיות חשוב. ניקוד מתוך 12: ראיות מדויקות 4, משמעות וגבולות 4, מקרה סותר 2, רפלקציה 2. מקבלים פרשנות חלופית מנומקת.')}<a href="#qual">לטבלת הקידוד המלאה ←</a>`;}
function escapeRoom(){return `<p>25 דקות. לכל תחנה ספרה, מקור ונימוק. המספרים נבדקים אוטומטית; מילוי הנימוק אינו בדיקת נכונותו. בדקו עם המפתח או המורה.</p>${[['כמה תלמידים אחרי ניקוי הכפילות? השתמשו בספרת העשרות.','עמ׳ 7 / תיק חינוכי'],['כמה הצדקות להשלמת חסר רק כי הכלי הציע?','עמ׳ 7, 18 / החלטת חסר'],['כמה מדדים: ממוצע, חציון, סטיית תקן?','עמ׳ 14 / מרכז ופיזור'],['כמה חיישנים עצמאיים ב־36 שורות?','עמ׳ 12 / תיק הנדסי']].map(([q,src],i)=>`<fieldset><legend>תחנה ${i+1}</legend><p>${q}</p>${num('lock-'+i,'ספרה',val('lock-'+i),0,9,1)}<label>מיקום הראיה<input type="text" id="lock-source${i}" data-save="lock-source${i}" value="${esc(val('lock-source'+i))}" placeholder="${src}"></label>${field('lock-reason'+i,'נימוק')}</fieldset>`).join('')}<button id="escape-check">פתיחת המנעול</button>${feedback('escape-feedback')}${field('escape-conclusion','כדי לצאת: תקנו ״AI הוכח כטוב יותר כי p קטן״ בעזרת דוגמה חינוכית והנדסית')}${solution('קוד 4036: 40 תלמידים→4; אפס הצדקות אוטומטיות→0; שלושה מדדים→3; שש יחידות→6. בחינוכי p=0.348 אינו קטן מ־0.05; בהנדסי התנודתיות יורדת והתגובה מואטת. מובהקות אינה החלטת תכנון. למתקדמים: בתחנה 3 אפשר יחס תגובה מעוגל ל־3, תוך דיווח היחס המדויק כ־2.758. ניקוד מורה 16: ספרות 4, ראיות 4, מסקנה 4, דיון 4.')}`;}
function svg(inner,label){return `<svg viewBox="0 0 560 310" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${inner}</svg>`;}
function dotPlot(a,title){const x=v=>55+(v-40)/70*460;return `<figure class="chart">${svg(`<text x="280" y="25" text-anchor="middle">${title}</text><line x1="55" y1="230" x2="515" y2="230" stroke="#748a9c"/>${[40,50,60,70,80,90,100,110].map(v=>`<text x="${x(v)}" y="255" text-anchor="middle">${v}</text>`).join('')}${a.map((v,i)=>`<circle cx="${x(v)}" cy="${210-a.slice(0,i).filter(z=>z===v).length*17}" r="7" fill="#087c76"/>`).join('')}<text x="280" y="290" text-anchor="middle">Score · simulated</text>`,'תצוגת נקודות: '+a.join(', '))}<figcaption>${title}: ממוצע ${fmt(Stats.mean(a),1)}, SD מדגמית ${fmt(Stats.sd(a))}.</figcaption></figure>`;}
function ciChart(results,labels,title){const lo=Math.min(0,...results.map(r=>r.low))-1,hi=Math.max(0,...results.map(r=>r.high))+1,x=v=>70+(v-lo)/(hi-lo)*420;return `<figure class="chart">${svg(`<text x="280" y="25" text-anchor="middle">${title}</text><line x1="${x(0)}" x2="${x(0)}" y1="45" y2="245" stroke="#7d91a0" stroke-dasharray="5"/>${results.map((r,i)=>{const y=75+i*150/Math.max(1,results.length-1);return `<line x1="${x(r.low)}" x2="${x(r.high)}" y1="${y}" y2="${y}" stroke="#137a88" stroke-width="3"/><circle cx="${x(r.difference)}" cy="${y}" r="6" fill="#1457b8"/><text x="70" y="${y-15}">${labels[i]}: ${fmt(r.difference)}</text>`;}).join('')}<line x1="70" y1="260" x2="490" y2="260" stroke="#718799"/>${[0,1,2,3,4].map(i=>{const v=lo+(hi-lo)*i/4;return `<text x="${x(v)}" y="285" text-anchor="middle">${fmt(v,1)}</text>`;}).join('')}`,'אומדנים ורווחי סמך 95% להפרש')}<figcaption>הקו הוא אי־ודאות באומדן ההפרש, ולא פיזור ציוני תלמידים. טווחים מספריים: ${results.map((r,i)=>`${labels[i]} [${fmt(r.low)}, ${fmt(r.high)}]`).join('; ')}.</figcaption></figure>`;}
function scatter(points,title,xlabel='X',ylabel='Y'){const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y)),dx=(maxX-minX)||1,dy=(maxY-minY)||1,x=v=>70+(v-minX)/dx*420,y=v=>245-(v-minY)/dy*180;return `<figure class="chart">${svg(`<text x="280" y="22" text-anchor="middle">${title}</text><line x1="65" y1="250" x2="500" y2="250" stroke="#748999"/><line x1="65" y1="45" x2="65" y2="250" stroke="#748999"/>${[0,1,2,3,4].map(i=>{const a=minX+dx*i/4,b=minY+dy*i/4;return `<text x="${x(a)}" y="272" text-anchor="middle">${fmt(a,1)}</text><text x="55" y="${y(b)+4}" text-anchor="end">${fmt(b,1)}</text>`;}).join('')}${points.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="4.5" fill="${p.g==='AI'||p.g==='A'?'#127f8e':'#ba5e2c'}" opacity=".85"/>`).join('')}<text x="280" y="302" text-anchor="middle">${xlabel}</text><text x="18" y="155" transform="rotate(-90 18 155)" text-anchor="middle">${ylabel}</text>`,'תרשים פיזור מדומה '+title)}<figcaption>${points.length} נקודות. כחול־ירקרק: AI או A; כתום: CONTROL או B. זהו קשר מתואר, לא הוכחה לסיבתיות.</figcaption></figure>`;}
function histogram(a,title){const min=Math.min(...a),max=Math.max(...a),bins=24,counts=Array(bins).fill(0),range=max-min||1;a.forEach(v=>counts[Math.min(bins-1,Math.floor((v-min)/range*bins))]++);const peak=Math.max(...counts);return `<figure class="chart">${svg(`<text x="280" y="24" text-anchor="middle">${title}</text>${counts.map((n,i)=>`<rect x="${55+i*19}" y="${245-n/peak*180}" width="17" height="${n/peak*180}" fill="#157b86"/>`).join('')}<line x1="50" x2="515" y1="245" y2="245" stroke="#748999"/>${[0,1,2,3,4].map(i=>`<text x="${55+i*114}" y="270" text-anchor="middle">${fmt(min+range*i/4,1)}</text>`).join('')}<text x="280" y="300" text-anchor="middle">Sample mean · score points</text><text x="25" y="150" transform="rotate(-90 25 150)" text-anchor="middle">Frequency (max ${peak})</text>`,'התפלגות של '+a.length+' ממוצעי מדגמים')}<figcaption>התפלגות ממוצעים, לא התפלגות ציוני אנשים. ${a.length} חזרות, מרכז ${fmt(Stats.mean(a))}, SD הממוצעים ${fmt(Stats.sd(a))}.</figcaption></figure>`;}
const SIM_NAMES=['מפעל המדגמים','מעבדת גודל המדגם','מתאם מסתורי','מסקנה על תנאי'];
function sims(){return head('ארבע סימולציות · עמ׳ 19–21','מנבאים. מריצים. מסבירים.','מימוש JavaScript מקומי לרעיונות סימולציות ה־Python שבמסמך. מחולל אקראי אחר נותן תוצאות שונות באותו מספר זרע; זהו שחזור בתוך האתר, לא שכפול ביט־לביט של פלטי Python.')+tabs(SIM_NAMES,'sim',sim)+notice()+`<section class="panel"><h2>${SIM_NAMES[sim]}</h2>${[simFactory,simPower,simMystery,simSensitivity][sim]()}</section>`;}
const seedField=()=>num('seed','זרע לשחזור',81626,0,4294967295,1);
function simFactory(){return `<p>אוכלוסייה נורמלית מדומה עם ממוצע אמיתי 70. מבצעים 2,000 דגימות ומציגים את ממוצעיהן. נסו n=10 ואז n=100; מה יקרה למרכז ולפיזור?</p>${field('sim-predict0','חיזוי לפני ההרצה ונימוק')}<div class="inputs">${num('sample-n','n בכל מדגם',10,2,500,1)}${num('sigma','SD באוכלוסייה',12,1,50,1)}${seedField()}</div><button id="run-factory">הרצת 2,000 מדגמים</button><div id="sim-result" role="status"></div>${field('sim-explain0','השוו אמפירי לתאורטי והסבירו את ההבדל')}${solution('SE(mean)=sigma/√n. בהגדלת n פי 10, SE קטן פי √10; המרכז נשאר בקירוב 70. סימולציה סופית מוסיפה רעש מונטה־קרלו. במדריך Python: 3.861 מול 3.795 ב־n=10; 1.181 מול 1.200 ב־n=100. חלופה ללא מחשב: דגימה חוזרת עם החזרה מאותה ערימת ציונים; זו אוכלוסייה אחרת מהנורמלית.')}`;}
function simPower(){return `<p>שתי קבוצות עצמאיות נורמליות, Welch דו־צדדי, α=0.05. delta הוא הפרש אמיתי שהוגדר במודל. נחשב שיעור דחיות ב־2,000 חזרות.</p>${field('sim-predict1','חזו מה יקרה כשתגדילו n, תכפילו SD או תשנו delta')}<div class="inputs">${num('sample-n','n לכל קבוצה',30,3,200,1)}${num('sigma','SD בכל אוכלוסייה',12,1,50,1)}${num('delta','הפרש אמיתי במודל',3,-20,20,1)}${seedField()}</div><button id="run-power">הרצת 2,000 ניסויים</button><div id="sim-result" role="status"></div>${field('sim-explain1','מדוע שיעור הדחייה אינו סיכוי שההשערה נכונה?')}${solution('ב־delta=0 הדחיות הן שגויות בסיפור, ובממוצע השיעור קרוב ל־0.05. ב־delta≠0 זה אומדן עוצמה בתנאי המודל. המדריך: n=30,sigma=12 → שיעור 0.0535 ב־delta=0 ו־0.1655 ב־delta=3. האתר משתמש במחולל אחר ולכן אין לצפות לזהות. רוחב רווח תאורטי כאשר sigma ידועה מוצג בנפרד ממרווחי Welch. אין לבחור זרעים עד שמתקבל p רצוי.')}`;}
function simMystery(){return `<p>בקבוצה A, X בין 1 ל־5; בקבוצה B, X בין 6 ל־10. בתוך כל קבוצה Y עולה בקירוב עם X. הפרמטר offset מזיז את B למטה או למעלה.</p>${field('sim-predict2','חזו את כיוון המתאם הכולל לעומת המתאמים בתוך הקבוצות')}<div class="inputs">${num('offset','הזזת קבוצה B',-40,-60,20,1)}${seedField()}</div><button id="run-mystery">בניית תרשים וקשרים</button><div id="sim-result" role="status"></div>${field('sim-explain2','השוו offset=-40 ל־0. האם קשר בתוך קבוצה מוכיח סיבתיות?')}${solution('הבדלי רמה בין קבוצות יכולים להפוך את התמונה הכוללת. בוחנים הקשר ומערך לפני פיצול או איגום; שניהם עלולים לשבש הסקה כשהם אוטומטיים. ב־Python במדריך: כולל −0.825, בתוך קבוצות 0.922 ו־0.912. אין לפרש את offset אוטומטית כסיבה בעולם. חלופה: שתי עננות עולות על שקפים שמזיזים זו ביחס לזו.')}`;}
function simSensitivity(){return `<p>החליטו מראש איזו חלופה מוצדקת ולמה, ורק אז השוו את כולן. מטרת הניתוח אינה למצוא p קטן.</p>${field('sensitivity-before','לפני ההשוואה: שלמים, השלמה נאיבית או הוצאת S25 — מה מוצדק לבדיקה?')}<button id="run-sensitivity">השוואת כל שלוש החלופות</button><div id="sim-result" role="status"></div>${field('sensitivity-after','מה השתנה באומדן ובאי־ודאות? מדוע אין לבחור לפי p?')}${solution('השלמים: n=39, הפרש 1.797,p≈0.348. השלמת post בממוצע הכולל: n=40, הפרש 2.540,p≈0.209 — יוצרת מידע ומתעלמת מאי־ודאות החסר, ואינה המלצה. בלי S25: n=38, הפרש 2.053,p≈0.293 — בדיקת רגישות בלבד לערך אמיתי. S18 נשאר בניתוח השיפור כי שעות אינן דרושות. דיווח כל החלופות והנימוקים מאפשר לבחון את ההחלטה.')}`;}
function bars(base){const y=v=>250-(v-base)/(100-base)*190;return `<figure class="chart">${svg(`<text x="280" y="25" text-anchor="middle">Same means · baseline ${base}</text><line x1="65" y1="250" x2="500" y2="250" stroke="#718999"/>${[0,1,2,3,4].map(i=>{const v=base+(100-base)*i/4;return `<text x="55" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}</text>`;}).join('')}${[68,72].map((v,i)=>`<rect x="${130+i*200}" y="${y(v)}" width="110" height="${250-y(v)}" fill="${i?'#117b8b':'#b65f2c'}"/><text x="${185+i*200}" y="${y(v)-10}" text-anchor="middle">${v}</text><text x="${185+i*200}" y="274" text-anchor="middle">${i?'B':'A'}</text>`).join('')}<text x="280" y="302" text-anchor="middle">Score · numerical example, not education means</text>`,'ממוצעים 68 ו־72 עם בסיס ציר '+base)}<figcaption>דוגמה מספרית נפרדת. יחס גבהים ${fmt((72-base)/(68-base))}; יחס ציונים ${fmt(72/68)}.</figcaption></figure>`;}
function graphs(){const pairs=cleanRows.filter(r=>r.hours!==null&&r.post!==null),c=Stats.corr(pairs.map(r=>r.hours),pairs.map(r=>r.post)),small=pairs.filter(r=>r.id!=='S25'),c2=Stats.corr(small.map(r=>r.hours),small.map(r=>r.post));return head('ציר · מכנה · יחידה · אי־ודאות','אותם מספרים יכולים לספר סיפור אחר')+`<section class="panel"><h2>עמודות עם בסיס משתנה</h2><div class="inputs"><label>בסיס הציר הימני<input type="range" id="axis" min="0" max="65" value="0"><output id="axis-output">0</output></label></div><div class="plot-grid"><div>${bars(0)}</div><div id="axis-chart">${bars(0)}</div></div><p class="note">בבסיס 65 יחס הגבהים הוא 7/3, אך 72 אינו יותר מכפול 68. הציר הקטוע מסומן ואפשר לבדוק את האפקט. זו דוגמה נפרדת, לא ממוצעי הקבוצות מהתיק החינוכי.</p>${field('graph-title','כותרת מתוקנת: יחידה, קבוצה, מקור ומספר יחידות')}</section><section class="panel"><h2>שעות–סיום: קשר ורגישות</h2>${scatter(pairs.map(r=>({x:r.hours,y:r.post,g:r.group})),'Synthetic education data','Study hours','Post score')}<p><b>עם S25:</b> n=${c.n},r=${fmt(c.r)},p=${fmt(c.p,4)}. <b>ללא S25:</b> n=${c2.n},r=${fmt(c2.r)},p=${fmt(c2.p,4)}.</p><p>שינוי טיפול יכול לשנות אומדן ומסר. S25 אמיתי בסיפור, ולכן מציגים את שתי התוצאות ואת סיבת הבדיקה. שעות נמדדו במהלך ההתערבות ועשויות להיות קשורות למוטיבציה ולתנאי; אין להכניס אותן אוטומטית כמשתנה בקרה סיבתי.</p>${field('graph-correlation','הסבירו מדוע זה אינו מוכיח ששעה נוספת תעלה לכל תלמיד את הציון')}</section><section class="panel"><h2>קו אי־ודאות להפרש</h2>${ciChart([Stats.educational(cleanRows)],['AI − CONTROL'],'Welch 95% confidence interval')}${quiz('graph-ci','מה מייצג הטווח?',['טווח ציוני תלמידים','אי־ודאות באומדן הפרש השיפור'],1,'זהו רווח סמך להפרש בין ממוצעי gain; אינו פיזור ציונים ואינו הוכחת שקילות.')}</section>`;}
function portfolio(){return head('מסכמים · מגנים · מעבירים לחדש','התיק שלי','העבודה נשמרת בדפדפן בלבד, בלי שליחה לשרת. ייצאו גיבוי אם עוברים למחשב אחר. אין הערכה אוטומטית של איכות הנימוקים.')+`<section class="panel"><h2>תיק שחזור</h2><span class="saved save-state">שמירה במכשיר זה</span>${field('final-question','שאלה, מילון, יחידת ניתוח ואומדן')}${field('final-clean','קובץ מקור ויומן ניקוי: החלטות וראיות')}${field('final-method','ניתוח שנבחר, תנאים ומגבלות')}${field('final-code','קוד או נוסחאות ובדיקה עצמאית של חישוב')}${field('final-graph','תיאור גרף: יחידות, n, תוצאה ואי־ודאות')}${field('final-ai','כלי ותאריך, גרסה ומסלול, הוראה, פלט שנבדק, טענה שנדחתה והסיבה')}${field('final-conclusion','מסקנה אישית: 100–150 מילים') }<div class="counter" id="word-count"></div>${field('final-reflection','רפלקציה: איזו החלטה שיניתם ולמה?')}${field('final-defense','הגנה של שתי דקות: יחידה, שינוי ניקוי, מגבלה וחישוב אחד ללא העתקת פלט')}${solution('דוגמה טובה: בתיק המדומה הפרש השיפור בין AI לביקורת היה כ־1.8 נקודות עם CI של כ־[−2.0,5.6] על 39 תלמידים עם זוג ציונים. אין הוכחת יתרון או שקילות. בשש יחידות חיישן המסנן הפחית תנודתיות אך האריך תגובה; התאמה ליישום דורשת סף ובדיקות נוספות. זו דוגמה קצרה לרכיבי מסקנה, ולא תחליף להגשה מלאה בת 100–150 מילים.')}<div class="export-actions"><button id="export-work" class="primary">ייצוא כל העבודה כ־JSON</button><button id="print-work">הדפסת העמוד</button><button id="reset-work">איפוס העבודה במכשיר</button></div>${feedback('export-feedback')}</section><section class="panel"><h2>משימת העברה — ללא AI</h2><p>שלושה חיישנים לפני עדכון ואחריו, עשר מדידות בכל מצב בכל יחידה. כל מדידות ״אחרי״ נערכו ביום חם יותר; אין מדידות ייחוס בתנאי יום זהים.</p>${table(['יחידה','שגיאה ממוצעת לפני °C','אחרי °C'],[['U1',2,1],['U2',3,2.5],['U3',1,1]])}<p>זמן התגובה בכל היחידות עלה מ־100 ל־180 ms. פלט שגוי: ״60 חיישנים עצמאיים הוכיחו שהעדכון משפר את כולם ב־50%, ולכן חייבים להתקין בכל מערכת.״</p><div class="inputs">${num('transfer-units','מספר יחידות')}${num('transfer-count','מספר מדידות כולל')}${num('transfer-before','ממוצע שגיאה לפני')}${num('transfer-after','ממוצע שגיאה אחרי')}${num('transfer-abs','ירידה מוחלטת °C')}${num('transfer-pct','ירידה יחסית %')}${num('transfer-ms','תוספת תגובה ms')}${num('transfer-response','עלייה יחסית בתגובה %')}</div><button id="transfer-check">בדיקת החישובים</button>${feedback('transfer-feedback')}${field('transfer-all','בדקו את המילה ״כולם״, הסבירו ערבוב יום וחום והציעו מסקנה ונתון נוסף')}${solution('3 יחידות ו־60 מדידות. לפני 2.0 ואחרי 1.5; ירידה 0.5°C או 25% מבסיס 2.0. U3 לא השתפר. תגובה +80ms,+80%. ערבוב יום/חום עם העדכון מונע ייחוס סיבתי נקי. דרושים תנאים דומים, סדר מאוזן, יותר יחידות ודרישות יישום. אין צורך ב־p. ניקוד מורה 10: יחידה 2, חישוב 2, תיקון ״כל״ 1, תגובה 1, ערבוב 2, מסקנה ונתון נוסף 2.')}</section><section class="panel"><h2>מחוון 0–3 עם משקלי המקור</h2><p>הערכה עצמית או עם מורה. הציון משקל×רמה/3; אין נקודות על p קטן או זהות לפלט AI.</p><div class="rubric-grid">${RUBRIC.map((r,i)=>`<article><h3>${r[0]} · ${r[1]}%</h3>${select('rubric-'+i,'רמת שליטה',[`0 — ${r[5]}`,`1 — ${r[4]}`,`2 — ${r[3]}`,`3 — ${r[2]}`],val('rubric-'+i))}</article>`).join('')}</div><p>ציון עצמי: <strong id="rubric-total">${rubricTotal()}</strong>/100</p>${field('rubric-feedback','החלטה אחת שנומקה היטב והחלטה אחת לתיקון')}<p class="small">ללא משימה איכותנית, המורה יכול להעביר מראש את 10 הנקודות לראיות ופרשנות ולהודיע לפני הביצוע. המחוון באתר מציג את המשקלים המקוריים.</p></section>`;}
function rubricTotal(){return fmt(RUBRIC.reduce((s,r,i)=>s+r[1]*(Number(val('rubric-'+i))||0)/3,0),1);}
const REFERENCES=[
['GAISE II (2020)','https://www.amstat.org/asa/files/pdfs/GAISE/GAISEIIPreK-12_Full.pdf','חלקים נבחרים: מחזור, הקשר ורמות הוראה; לא כל 126 העמודים.'],['Garfield (2002), Statistical Reasoning','https://jse.amstat.org/v10n3/garfield.html','הגדרות, דיון והשלכות בטקסט הזמין; לא ניתוח מחדש של המחקרים.'],['ASA (2016), p-values','https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf','מסמך העקרונות נבדק; אינו ניסוי התערבות.'],['UCLA OARC, Choosing a statistical test','https://stats.oarc.ucla.edu/other/mult-pkg/whatstat/','טבלת הנחיה רשמית; אין להשתמש בה בלי מערך ותנאים.'],['Braun & Clarke (2022), Thematic analysis','https://doi.org/10.1080/26895269.2022.2129597','תקציר וקטעים מאונדקסים; אתר המחברות נחסם בבדיקה.'],['Fetters et al. (2013), Mixed methods integration','https://doi.org/10.1111/1475-6773.12117','מבוא ועקרונות בטקסט הזמין; לא כל הדוגמאות.'],['Prescott et al. (2024)','https://doi.org/10.2196/54482','שיטות, תוצאות ומגבלות רלוונטיות בטקסט המו״ל; לא כל ההשלמות.'],['Chelli et al. (2024), e53164','https://doi.org/10.2196/53164','הגדרה, שיטות ותוצאות רלוונטיות; משימת הפניות אינה מבחן ניתוח נתונים.'],['Bastani et al. (2025)','https://doi.org/10.1073/pnas.2422633122','תקציר ורשומות; הודעת תיקון אותרה ולא נקראה במלואה. אין שימוש באומדני השפעה כאן.'],['Kestin et al. (2025)','https://doi.org/10.1038/s41598-025-97652-6','תקציר וקטעי דיון מאונדקסים; הכללה מוגבלת ליחידה.'],['מדריך תיקון 13 — הרשות להגנת הפרטיות','https://www.gov.il/he/pages/guide_tikon13_professional','רשומה ואזור רשמי אותרו; גוף המדריך לא נפתח. אין כאן פרשנות משפטית.'],['המלצות לשימוש אישי ב־AI','https://www.gov.il/he/pages/ai_147','תקציר רשמי והמלצות מאונדקסות; הגוף לא נפתח. תחולת שימוש אישי אינה אישור מוסדי.'],['משרד החינוך — הנחיות AI','https://meyda.education.gov.il/files/Pop/0files/lemida-metukshevet/AI/Guidelines.pdf','רשומה וקובץ אותרו; פתיחת PDF נחסמה. אין בסיס לפירוט הרשאות כאן.'],['OpenAI — Data analysis','https://help.openai.com/en/articles/8437071-data-analysis-with-chatgpt','תיעוד על ניתוח קוד ובדיקת פלט.'],['Microsoft — Python in Excel','https://support.microsoft.com/en-us/excel/python/introduction-to-python-in-excel','יכולות, רישוי ומיקום עיבוד בתיעוד; לא בדיקה בכל מסלול.'],['IBM — SPSS Statistics','https://www.ibm.com/products/spss-statistics','תיאורי מוצר ורישוי אקדמי; לא חוזי מחיר או כל גרסת שרת.'],['jamovi documentation','https://docs.jamovi.org/index.html','תיעוד ופרטי חופשיות ושימוש ב־R.'],['Google Sheets AI function','https://support.google.com/docs/answer/15877199','תיעוד ו־Experiments; גישה, שפה ותכונות משתנות בין מסלולים.'],['NVivo AI Cloud / security','https://lumivero.com/legal-information/security-and-compliance/','תיאורי Desktop מול Cloud ומדיניות מוצהרת.'],['ATLAS.ti — Intentional AI Coding','https://manuals.atlasti.com/Win/en/manual/SearchAndCode/IntentionalAICoding.html','תיאור העלאת תוכן לשרתים לפעולות AI.'],['MAXQDA — Local AI','https://www.maxqda.com/help/ai-assist/local-ai/requirements-and-setup?view=full','מסלול מקומי מול ענן ודרישות זכאות.']
];
function teacher(){return head('מפת הוראה · מקורות · שישה פרומפטים','למורה ולחוקר הצעיר','האתר מבוסס על המדריך שסופק, מתאריך 16.10.2026. תיאורי המחקרים, מצב הקריאה והכלים מובאים כסקירת המקור המתוארכת; אין כאן בדיקת ספקים חדשה.')+`<section class="panel"><h2>כיסוי יחידת ההוראה</h2>${table(['עמודים במדריך','מימוש באתר'],[['1–6: יסודות, סקירה וביקורת מצגת','דף זה, מילון מושגים וארבעה מפגשים'],['7–13: תיקים וניקוי ושילוב','תיק חינוכי, קולות ותמות, חיישנים וטבלת שילוב'],['14–18: משחקים וגרפים','כל ששת המשחקים ועמוד הגרפים'],['19–21: סימולציות Python','ארבע סימולציות בדפדפן; גרסאות אלגוריתם שונות מסומנות'],['22–26: כלים, פרטיות ופרומפטים','מפת כלים, גבולות שימוש ושש תבניות'],['27–32: מפגשים והערכה','ארבעה מערכי 90 דקות, תיק עבודות, מחוון והעברה'],['33–35: מקורות','21 רשומות וקישורי ההשלמה להלן עם מגבלות קריאה'],['36–38: נתונים מלאים','41 שורות חינוך ו־36 מדידות חיישנים מהנספח, עם הורדת CSV']])}<p>ארבעת המפגשים כוללים גרסאות קצרות של הסימולציות. חדר הבריחה, מעבדת גודל המדגם המלאה והגנה אישית לכולם דורשים הרחבה. בתיכון אפשר להסתפק בתיאור מנומק; בי״ג–י״ד מוסיפים קוד, הנחות, אומדן ורווח סמך כשמתאימים.</p></section><section class="panel"><h2>מה נשמר ומה תוקן במצגת המקור</h2>${table(['שקופיות','הבהרה להוראה'],[['3: כמותי, איכותני ומשולב','שלושה מסלולים, לא רצף חובה. שילוב דורש אינטגרציה מפורשת.'],['4,7: בחירת מבחן','יחידה, הקצאה, זיווג, עצמאות ואשכולות לפני שם המבחן; נורמליות אינה מתג יחיד.'],['5: שורה היא נבדק','בטבלת אורך שורה עשויה להיות מדידה. מזהה חוזר אינו בהכרח כפילות.'],['6: הסרת כפילויות וחריגים','מאתרים ובודקים לפני הסרה; חריג אמיתי נשאר או נבחן ברגישות מתועדת.'],['8,10: שקיפות תוכנה','דיוק תלוי נתונים, הגדרות ואלגוריתם; גם תפריט יכול להפעיל מבחן לא מתאים.'],['9,10: AI מול חישוב','מודל יכול לכתוב קוד לאותו מנוע; בדקו קלט וקוד, לא רק שמות מוצרים.'],['11: ניתוח תמטי','תהליך חוזר; תמה היא דפוס משמעות, לא שכיחות בלבד.'],['16: פרטיות','קוד במקום שם הוא פסאודונימיזציה, לא בהכרח אנונימיות.'],['17: תיעוד','שומרים מקור, שינויים, קוד, גרסה והחלטות כדי לאפשר בדיקה.']])}<p class="note">שתי כיתות בלבד עם מורה ותנאי שונים אינן מזהות בנפרד את השפעת AI. הגדלת מספר התלמידים באותן שתי כיתות אינה מתקנת את הערבוב.</p></section><section class="panel"><h2>גבולות הראיות המחקריות</h2><p>הסקירה ממוקדת לתכנון הוראה, לא מטא־אנליזה או סקירה שיטתית ממצה. היחידה עצמה לא נבחנה בניסוי בישראל. זמני הפעילויות והמחוון הם הצעת תכנון, ולא אומדן לשיפור צפוי.</p><p>ב־Chelli מספר הפרסום הנכון e53164. שיעורי 28.6%,39.6%,91.4% מתייחסים לשחזור הפניות בסקירות רפואיות ולגרסאות מודלים שנבדקו; אין להסיק מהם דיוק של t או קוד ב־2026.</p><p>Prescott ניתחו 40 הודעות תזכורת קצרות, לא ראיונות גולמיים של 40 משתתפים. התאמת 5 מתוך 7 תמות אינה הסכמה בכל קטע; דווחו גם 36%–47% הסכמה בתנאים שונים. 20 לעומת 567 דקות הן תוצאות משימה מסוימת, לא הבטחת חיסכון גורפת. ארבעה מקודדים אנושיים פעלו בשני צוותים.</p><p>דיווחי Samsung מוצגים במקור כרקע תקשורתי בלבד, ללא הודעה ראשונית מלאה שמאמתת את כל ציר הזמן. אין להשתמש בהם כראיה משפטית או כמדיניות ספק נוכחית. המקורות תומכים בהכוונה, בבדיקת הבנה ובהעברה עצמאית, לא בטענה שכל AI עוזר או פוגע באותה דרך.</p></section><section class="panel"><h2>כלים ותהליך שניתן לשחזר</h2>${table(['כלי / מסלול','תפקיד והבחנה לפי הסקירה המתוארכת'],[['Excel','ניקוי, נוסחאות וציר. שומרים טווחים ו־STDEV.S; אחסון וסנכרון תלויי הגדרות.'],['SPSS','תפריטים ותחביר; רישוי מוסדי/מסחרי; Desktop אינו כל שירות שרת.'],['jamovi','חלופה פתוחה עם ממשק ו־R; שומרים omv והגדרות. מסלול ענן אינו מקומי.'],['Python / R','קוד וספריות פתוחות; שומרים גרסאות, מקור וזרע. מחברת בענן משנה את מקום העיבוד.'],['ChatGPT','הצעת ניתוח, כתיבת קוד והסבר. בקשו קוד, קלט ויומן; בדקו פלט ולא רק ניסוח.'],['Copilot in Excel','פעולות ועזרה בגיליון לפי זכאות. Python in Excel מחושב בענן Microsoft, לא בהכרח מקומית.'],['Gemini in Sheets','סיוע וסיווג; פונקציית AI אינה תחליף לפונקציה מספרית דטרמיניסטית.'],['NVivo','קידוד ואחזור; מבחינים Desktop מ־AI Cloud ותלות במסלול.'],['ATLAS.ti','קידוד ידני ו־Intentional AI; תיעוד המקור מתאר העלאת תוכן לפעולות AI.'],['MAXQDA','סיכומים וקידוד; Local AI דורש תצורה וזכאות ואינו בהכרח מחשב התלמיד.'],['מסמך וגיליון','מספיקים ל־12 תשובות: מזהה, ציטוט וקוד, עם יומן פרשנות.']])}<p>אין צורך ברכישה או בחשבון כדי להשלים אתר זה. לפני שיעור עם מוצר אחר בודקים קובץ קצר: סוגי נתונים, n, חסר מול אפס, זיווג, עברית וסלנג, גרף וציטוט מדויק. התאמה בין שני ממשקים לאותו קוד אינה בדיקה מתודולוגית עצמאית.</p><details><summary>חישוב ושחזור בגיליון</summary><p>פתחו עותק נקי. חשבו gain רק בזוג ציונים שלם. סננו לפי קבוצה; AVERAGE, MEDIAN ו־STDEV.S על טווחים מספריים. T.TEST דו־זנבי מסוג 3 או jamovi/JASP עם Welch על השיפורים. בדקו שהטווחים באמת מייצגים את הקבוצות. הבדלי STDEV.P לעומת STDEV.S, טווח או זיווג עלולים להסביר אי־התאמה.</p><pre class="code">gain = post - pre
SE = sqrt(s_AI**2/n_AI + s_CONTROL**2/n_CONTROL)
t = (mean_AI - mean_CONTROL) / SE</pre><p>האתר מחשב ב־JavaScript. קובצי reproduce.py ו־simulations.py שהמדריך מזכיר לא צורפו לבקשה; האתר אינו מציג אותם כאילו סופקו או הורצו.</p></details></section><section class="panel"><h2>פרטיות ואחריות</h2><p>לתרגול משתמשים בנתונים המדומים בלבד. החלפת שם בקוד אינה מבטיחה אנונימיות; קול, סיפור נדיר, טבלת קישור או צירוף מאפיינים עשויים לזהות. אל תעלו לשירות חיצוני ציונים מזוהים או סיפורים אישיים לצורך תרגיל זה.</p><p>המדריך מבחין בין דין, מדיניות מוסדית והמלצת הוראה. הוא אינו חוות דעת משפטית ואינו קובע היתר מוסדי. לפני שימוש תלמיד בחשבון חיצוני פועלים לפי ההרשאות וההנחיות שהמוסד מסר. כיבוי אימון אינו שקול לאי־אחסון או לאי־העברה. אפשר להמשיך בכל פעילויות האתר בלי חשבון כזה.</p></section><section class="panel"><h2>שישה פרומפטים לבדיקה, לא להחלפת שיקול דעת</h2>${PROMPTS.map(([title,text],i)=>`<details><summary>${i+1}. ${title}</summary><p id="prompt-${i}">${text}</p><button data-copy="${i}">העתקת הפרומפט</button>${feedback('copy-'+i)}</details>`).join('')}${field('prompt-audit','בחרו פלט: האם ספר נכון יחידות? השלים ללא רשות? ערבב חקרני ועיקרי? אמתו טענה אחת ישירות.')}</section><section class="panel"><h2>מקורות ומצב הקריאה לפי המדריך</h2><p>הרשומות להלן משמרות את גבולות הסקירה מ־16.10.2026. הן אינן טענה שקראנו מחדש כל מקור באתר זה.</p>${REFERENCES.map(([title,url,status],i)=>`<article class="ref"><h3><a href="${url}" target="_blank" rel="noopener">[${i+1}] ${title}</a></h3><p>${status}</p></article>`).join('')}<details><summary>קישורי המשך הכלולים ברשומות המקור</summary><ul>${[['Braun & Clarke FAQ','https://www.thematicanalysis.net/faqs/'],['Bastani — הודעת תיקון','https://doi.org/10.1073/pnas.2518204122'],['אזור הרשות להגנת הפרטיות','https://govextra.gov.il/privacy-protection-regulations/privacy-protection-regulations/'],['Python in Excel security','https://support.microsoft.com/en-us/excel/python/data-security-and-python-in-excel'],['Python in Excel licensing','https://support.microsoft.com/en-us/office/python-in-excel-add-on-licensing-faq-6d90fc0e-f080-4799-9d28-9754c77fb308'],['jamovi about','https://www.jamovi.org/about.html'],['Google AI experiments','https://support.google.com/docs/answer/15820999'],['NVivo additional source','https://lumivero.com/classes-addition/'],['MAXQDA AI Assist','https://www.maxqda.com/help/ai-assist/what-is-ai-assist']].map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noopener">${t}</a></li>`).join('')}</ul></details></section>`;}
const routes={home,learn,education,qual,engineering,games,sim:sims,graphs,portfolio,teacher};
function render(){const route=location.hash.slice(1)||'home';main.innerHTML=(routes[route]||home)();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+route);if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});wordCount();}
function wordCount(){const el=document.getElementById('word-count');if(el){const n=String(val('final-conclusion')).trim().split(/\s+/).filter(Boolean).length;el.textContent=`${n} מילים · יעד 100–150 · ${n>=100&&n<=150?'בטווח':'מחוץ לטווח'}`;}}
function msg(id,text,good=true){const el=document.getElementById(id);el.innerHTML=text;el.classList.toggle('bad',!good);}
function readNum(id,min=-Infinity,max=Infinity,integer=false){const el=document.getElementById(id),s=el.value.trim(),n=Number(s);if(!s||!Number.isFinite(n)||n<min||n>max||(integer&&!Number.isInteger(n)))throw Error('בדקו ערך בשדה: '+(el.closest('label')?.textContent||id));return n;}
function numericCheck(ids,expected,tolerances,out,explanation){let score=0,lines=[];ids.forEach((id,i)=>{const el=document.getElementById(id),s=el.value.trim(),n=Number(s),ok=s!==''&&Number.isFinite(n)&&Math.abs(n-expected[i])<=tolerances[i];score+=ok;lines.push(`${ok?'✓':'○'} ${esc(el.closest('label').textContent)}: ${ok?'נכון':'הערך הצפוי '+fmt(expected[i])}`);work[id]=s;});save();msg(out,`<b>${score}/${ids.length} תשובות נכונות.</b><br>${lines.join('<br>')}<p>${explanation}</p>`,score===ids.length);}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csv(rows){const keys=Object.keys(rows[0]);return '\uFEFF'+keys.join(',')+'\r\n'+rows.map(r=>keys.map(k=>{const s=String(r[k]??'');return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function exportData(kind){let rows,name;if(kind==='raw'){rows=EDUCATION;name='education_raw.csv';}if(kind==='clean'){rows=cleanRows;name='education_clean.csv';}if(kind==='register'){rows=[{id:'S07',column:'post',verified_value:69}];name='source_register.csv';}if(kind==='cleanlog'){rows=CLEANING.map(r=>({id:r[0],issue:r[1],action:r[2],reason:r[3]}));name='cleaning_log.csv';}if(kind==='quotes'){rows=QUOTES.map(([id,quote])=>({id,quote}));name='qualitative_quotes.csv';}if(kind==='engineering'){rows=ENGINEERING;name='engineering_rounded_appendix.csv';}download(name,csv(rows),'text/csv;charset=utf-8');}
main.addEventListener('input',e=>{const el=e.target,k=el.dataset.save;if(k){work[k]=el.value;save();wordCount();}if(el.id?.startsWith('lock-')){work[el.id]=el.value;save();}if(el.id==='axis'){document.getElementById('axis-output').textContent=el.value;document.getElementById('axis-chart').innerHTML=bars(Number(el.value));}});
main.addEventListener('change',e=>{const k=e.target.dataset.save;if(k){work[k]=e.target.value;save();if(k.startsWith('rubric-'))document.getElementById('rubric-total').textContent=rubricTotal();}});
main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
if(b.dataset.lesson!==undefined){lesson=+b.dataset.lesson;render();return;}if(b.dataset.game!==undefined){game=+b.dataset.game;render();return;}if(b.dataset.sim!==undefined){sim=+b.dataset.sim;render();return;}
if(b.dataset.quiz){const ok=b.dataset.choice===b.dataset.answer;work['quiz-'+b.dataset.quiz]={choice:+b.dataset.choice,correct:ok};save();msg(b.dataset.quiz,(ok?'✓ נכון. ':'○ נסו לתקן. ')+b.dataset.explain,ok);return;}
if(b.dataset.download){exportData(b.dataset.download);return;}
if(b.dataset.copy!==undefined){const i=+b.dataset.copy;try{await navigator.clipboard.writeText(PROMPTS[i][1]);msg('copy-'+i,'הפרומפט הועתק.')}catch{msg('copy-'+i,'העתקה אוטומטית אינה זמינה. סמנו והעתיקו את הטקסט שמעל.');}return;}
switch(b.id){
case 'detect-check':{let n=0;CLEANING.forEach((r,i)=>{if(String(val('detect-'+i))===String(i))n++;});msg('detect-feedback',`${n}/6 החלטות נכונות. נימוקים וראיות דורשים בדיקה עצמית או מורה. ${n===6?'נכון: 40 תלמידים, 39 שיפורים, 38 זוגות שעות–סיום.':'פתחו את המפתח והשוו לכל החלטה.'}`,n===6);break;}
case 'spread-check':numericCheck(['spread-mean','spread-med','spread-ra','spread-rb','spread-sda','spread-sdb'],[70,70,4,40,Math.sqrt(2.5),Math.sqrt(250)],[.001,.001,.001,.001,.01,.02],'spread-feedback','אותו מרכז אינו אותה התפלגות. אין כאן נתונים המסבירים את סיבת השונות.');break;
case 'custom-check':{const a=document.getElementById('spread-custom').value.trim().split(/[,;\s]+/).map(Number);if(a.length!==5||!a.every(Number.isFinite))throw Error('הזינו חמישה מספרים מופרדים בפסיקים.');const s=Stats.summary(a),ok=Math.abs(s.mean-70)<.001&&Math.abs(s.median-70)>.001;msg('custom-feedback',`ממוצע ${fmt(s.mean)}, חציון ${fmt(s.median)}, SD=${fmt(s.sd)}. ${ok?'הקבוצה עומדת בתנאים.':'נדרש ממוצע 70 וחציון שונה מ־70.'}${dotPlot(a,'Your group')}`,ok);break;}
case 'analysis-check':{let n=0;ANALYSES.forEach((r,i)=>{if(String(val('analysis-'+i))===String(r[1]))n++;});msg('analysis-feedback',`${n}/6 בחירות תואמות למפתח. תנאים, שאלות הבהרה וחלופות מנומקות נבדקים עם המורה; הם חלק מהמשימה.`,n===6);break;}
case 'escape-check':{const digits=[4,0,3,6],right=digits.every((d,i)=>document.getElementById('lock-'+i).value.trim()!==''&&Number(document.getElementById('lock-'+i).value)===d),filled=digits.every((d,i)=>String(val('lock-source'+i)).trim()&&String(val('lock-reason'+i)).trim());msg('escape-feedback',right&&filled?'✓ הקוד 4036 נפתח. עכשיו בדקו את איכות הראיות עם המפתח ותקנו את המסקנה למטה.':!right?'הספרות עדיין אינן תואמות. בדקו תלמידים, הצדקה, מדדים ויחידות.':'הספרות נכונות, אך נדרש מיקום ראיה ונימוק לכל תחנה. מילוי טקסט אינו אישור לנכונותו.',right&&filled);work.escapeOpened=right&&filled;save();break;}
case 'filter-decision':{const ms=readNum('limit-ms',1,2000),sd=readNum('limit-sd',.001,2),u=unitMeans(),rawSD=Stats.mean(u.map(x=>x.rawSD)),fSD=Stats.mean(u.map(x=>x.filterSD)),rawMS=Stats.mean(u.map(x=>x.rawMS)),fMS=Stats.mean(u.map(x=>x.filterMS)),raw=rawSD<=sd&&rawMS<=ms,filter=fSD<=sd&&fMS<=ms;msg('filter-feedback',`RAW: ${raw?'עומד':'אינו עומד'} בשתי הדרישות בממוצע (SD=${fmt(rawSD,5)}, ms=${fmt(rawMS)}). FILTER: ${filter?'עומד':'אינו עומד'} (SD=${fmt(fSD,5)}, ms=${fmt(fMS)}). זו בדיקת ממוצעים בתרגיל, לא אישור רכיב לכל יחידה.`);break;}
case 'run-factory':{const n=readNum('sample-n',2,500,true),sigma=readNum('sigma',1,50),seed=readNum('seed',0,4294967295,true),r=Stats.factory(n,sigma,seed);work.lastFactory=r;save();document.getElementById('sim-result').innerHTML=`<div class="feedback">מרכז ${fmt(r.center)}, SD אמפירי של ממוצעים ${fmt(r.empirical)}, SE תאורטי ${fmt(r.theory)}. n=${n},sigma=${sigma},seed=${seed},reps=2000.</div>${histogram(r.means,'Sampling distribution of means')}<button data-result="lastFactory">הורדת תוצאת הסימולציה</button>`;break;}
case 'run-power':{const resultElement=document.getElementById('sim-result');const n=readNum('sample-n',3,200,true),sigma=readNum('sigma',1,50),delta=readNum('delta',-20,20),seed=readNum('seed',0,4294967295,true);b.disabled=true;b.textContent='מחשב 2,000 ניסויים…';await new Promise(r=>setTimeout(r,30));const r=Stats.power(n,sigma,delta,seed);work.lastPower=r;save();resultElement.innerHTML=`<div class="feedback"><strong>${r.rejected}/2000 דחיות = ${fmt(r.rate*100,2)}%</strong><p>${delta===0?'כאן מדובר בשיעור דחייה שגויה בסיפור האפס.':'כאן מדובר באומדן עוצמה בתנאי המודל.'} זה אינו סיכוי שההשערה נכונה.</p><p>רוחב CI תאורטי להפרש כש־sigma ידועה: ${fmt(r.width)} נקודות. אינו רוחב אמפירי של מרווחי Welch. n=${n},sigma=${sigma},delta=${delta},seed=${seed}.</p></div><button data-result="lastPower">הורדת תוצאת הסימולציה</button>`;b.disabled=false;b.textContent='הרצת 2,000 ניסויים';break;}
case 'run-mystery':{const offset=readNum('offset',-60,20),seed=readNum('seed',0,4294967295,true),r=Stats.mystery(offset,seed);work.lastMystery={...r,offset,seed};save();document.getElementById('sim-result').innerHTML=`<div class="feedback">r כולל=${fmt(r.all)}; בתוך A=${fmt(r.a)}; בתוך B=${fmt(r.b)}. 30 נקודות בכל קבוצה; offset=${offset},seed=${seed}. אין סיבתיות אוטומטית.</div>${scatter(r.points,'Grouped and pooled correlation')}<button data-result="lastMystery">הורדת תוצאת הסימולציה</button>`;break;}
case 'run-sensitivity':{const cases=['complete','impute','exclude'].map(m=>Stats.sensitivity(cleanRows,m).result);work.lastSensitivity=cases;save();document.getElementById('sim-result').innerHTML=table(['חלופה','n','הפרש gain','p','95% CI'],cases.map((r,i)=>[['שלמים','השלמה נאיבית — לא המלצה','ללא S25 — רגישות'][i],r.n,fmt(r.difference),fmt(r.p),`[${fmt(r.low)},${fmt(r.high)}]`]))+ciChart(cases,['Complete','Naive imputation','Without S25'],'Sensitivity · gain difference')+'<button data-result="lastSensitivity">הורדת התוצאות</button>';break;}
case 'transfer-check':numericCheck(['transfer-units','transfer-count','transfer-before','transfer-after','transfer-abs','transfer-pct','transfer-ms','transfer-response'],[3,60,2,1.5,.5,25,80,80],[0,0,.001,.001,.001,.01,0,.01],'transfer-feedback','חישוב נכון אינו פותר ערבוב של יום חם עם העדכון. U3 לא השתפר. הוסיפו מסקנה מוגבלת ונתון נוסף.');break;
case 'export-work':download('data-analysis-portfolio.json',JSON.stringify({schema:1,exportedAt:new Date().toISOString(),work},null,2),'application/json');msg('export-feedback','בקשת ההורדה נשלחה. הקובץ כולל תשובות וסימולציות שנשמרו במכשיר.');break;
case 'print-work':window.print();break;
case 'reset-work':if(confirm('למחוק את כל העבודה השמורה באתר במכשיר זה? מומלץ לייצא קודם.')){work={};localStorage.removeItem(KEY);render();}break;
default:if(b.dataset.result)download('simulation-'+b.dataset.result+'.json',JSON.stringify(work[b.dataset.result],null,2),'application/json');
}
}catch(err){const el=document.createElement('div');el.className='feedback bad';el.setAttribute('role','alert');el.textContent=err.message;b.after(el);b.disabled=false;if(b.id==='run-power')b.textContent='הרצת 2,000 ניסויים';}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
